"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  COVERAGE_PATH,
  DONOR_SHARES,
  formatDeltaValue,
  HEADLINE,
  INSTRUMENT_MIX,
  MDB_STACKS,
  REGION_GAPS,
  RESIDUAL_BEARERS,
  RESIDUAL_CONCENTRATION_CURVE,
  SOURCE_NOTE,
  SOURCES,
  TOP_K_LADDER,
  VINTAGE_DELTAS,
  fmtBn,
  fmtMultiple,
  fmtPct,
  rankedRegionsBy,
} from "@/data/adaptation-economics-concentration-2026q3-data";

// viz-types: Lorenz area+line, residual bars, MDB stacked bars, adapt share donut, coverage dual-axis path, gap bars, resilience??gap scatter, vintage dumbbells, donor bars, instrument pie | layout: default

type ViewId = "bearers" | "mdb" | "coverage" | "donors";
type LadderMetric = "sharePct" | "cumulativePct";
type GapMetric = "gapBn" | "gapSharePct" | "resiliencePct";
type IncomeFilter = "all" | "advanced" | "emerging" | "developing";
type CoverageMetric = "levels" | "share";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AdaptationEconomicsConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("bearers");
  const [ladderMetric, setLadderMetric] = useState<LadderMetric>("sharePct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [gapMetric, setGapMetric] = useState<GapMetric>("gapBn");
  const [incomeFilter, setIncomeFilter] = useState<IncomeFilter>("all");
  const [coverageMetric, setCoverageMetric] =
    useState<CoverageMetric>("levels");
  const [showMitigation, setShowMitigation] = useState(true);

  const residualBars = useMemo(() => {
    return [...RESIDUAL_BEARERS]
      .map((b) => ({
        ...b,
        value: ladderMetric === "sharePct" ? b.sharePct : b.cumulativePct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const regionBars = useMemo(() => {
    const sortKey =
      gapMetric === "resiliencePct"
        ? "resilience"
        : gapMetric === "gapSharePct"
          ? "share"
          : "gap";
    let rows = rankedRegionsBy(sortKey);
    if (incomeFilter !== "all") {
      rows = rows.filter((r) => r.income === incomeFilter);
    }
    return rows.map((r) => ({
      ...r,
      value:
        gapMetric === "gapBn"
          ? r.gapBn
          : gapMetric === "gapSharePct"
            ? r.gapSharePct
            : r.resiliencePct,
    }));
  }, [gapMetric, incomeFilter]);

  const scatterData = useMemo(() => {
    const rows =
      incomeFilter === "all"
        ? REGION_GAPS
        : REGION_GAPS.filter((r) => r.income === incomeFilter);
    return rows.map((r) => ({
      ...r,
      x: r.resiliencePct,
      y: r.gapBn,
      z: Math.max(80, r.gapSharePct * 12),
    }));
  }, [incomeFilter]);

  const donorBars = useMemo(
    () => [...DONOR_SHARES].sort((a, b) => b.sharePct - a.sharePct),
    [],
  );

  const mdbAdaptDonut = useMemo(
    () => [
      {
        id: "lmic",
        label: "LMIC adaptation",
        value: HEADLINE.mdbLmicAdapt2025Bn,
        fill: "#0ea5e9",
      },
      {
        id: "hic",
        label: "HIC adaptation",
        value: HEADLINE.mdbHicAdapt2025Bn,
        fill: "#14b8a6",
      },
    ],
    [],
  );

  const dumbbellRows = useMemo(() => {
    return VINTAGE_DELTAS.map((d) => ({
      ...d,
      low: Math.min(d.priorValue, d.newestValue),
      high: Math.max(d.priorValue, d.newestValue),
      prior: d.priorValue,
      newest: d.newestValue,
    }));
  }, []);

  return (
    <div
      className="space-y-6"
      data-viz="adaptation-economics-concentration-2026q3"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300/90">
          Adaptation economics ??? Q3 2026 concentration lens
        </p>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-200 sm:text-base">
          Residual Top-1 ({HEADLINE.top1BearerLabel}) still holds{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top1BearerSharePct)}
          </span>
          ; Top-3 clears{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top3BearerSharePct)}
          </span>
          . MDB LMIC adaptation is{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.mdbLmicShareOfAllAdaptPct)}
          </span>{" "}
          of all-economy MDB adapt ({fmtBn(HEADLINE.mdbLmicAdapt2025Bn)} of{" "}
          {fmtBn(HEADLINE.mdbAllAdapt2025Bn)}), while H1 2026 insured share of
          economic loss sits at{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.h1InsuredShare2026Pct)}
          </span>
          .
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Residual Top-1
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {fmtPct(HEADLINE.top1BearerSharePct)}
            </p>
            <p className="text-[11px] text-slate-400">Households &amp; SMEs</p>
          </div>
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Residual Top-3
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {fmtPct(HEADLINE.top3BearerSharePct)}
            </p>
            <p className="text-[11px] text-slate-400">
              HHI {HEADLINE.residualHhi.toLocaleString("en-US")}
            </p>
          </div>
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              MDB LMIC of adapt
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {fmtPct(HEADLINE.mdbLmicShareOfAllAdaptPct)}
            </p>
            <p className="text-[11px] text-slate-400">
              {fmtBn(HEADLINE.mdbLmicAdapt2025Bn)} /{" "}
              {fmtBn(HEADLINE.mdbAllAdapt2025Bn)}
            </p>
          </div>
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Needs / MDB mid
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {fmtMultiple(HEADLINE.needsVsMdbMultipleMid)}
            </p>
            <p className="text-[11px] text-slate-400">
              H1 cover {fmtPct(HEADLINE.h1InsuredShare2026Pct)}
            </p>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-4">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "bearers", label: "Residual bearers" },
            { id: "mdb", label: "MDB books" },
            { id: "coverage", label: "Gaps & coverage" },
            { id: "donors", label: "Donors & vintage" },
          ]}
        />
        {view === "bearers" && (
          <>
            <ToggleGroup
              label="Metric"
              value={ladderMetric}
              onChange={setLadderMetric}
              options={[
                { id: "sharePct", label: "Share %" },
                { id: "cumulativePct", label: "Cumulative %" },
              ]}
            />
            <label className="flex items-center gap-2 text-sm text-slate-600">
              <input
                type="checkbox"
                checked={showEqualLine}
                onChange={(e) => setShowEqualLine(e.target.checked)}
                className="rounded border-slate-300"
              />
              Equal-split line
            </label>
          </>
        )}
        {view === "mdb" && (
          <label className="flex items-center gap-2 text-sm text-slate-600">
            <input
              type="checkbox"
              checked={showMitigation}
              onChange={(e) => setShowMitigation(e.target.checked)}
              className="rounded border-slate-300"
            />
            Show mitigation stack
          </label>
        )}
        {view === "coverage" && (
          <>
            <ToggleGroup
              label="Gap metric"
              value={gapMetric}
              onChange={setGapMetric}
              options={[
                { id: "gapBn", label: "Gap $" },
                { id: "gapSharePct", label: "Gap share %" },
                { id: "resiliencePct", label: "Resilience %" },
              ]}
            />
            <ToggleGroup
              label="Income"
              value={incomeFilter}
              onChange={setIncomeFilter}
              options={[
                { id: "all", label: "All" },
                { id: "advanced", label: "Advanced" },
                { id: "emerging", label: "Emerging" },
                { id: "developing", label: "Developing" },
              ]}
            />
            <ToggleGroup
              label="Coverage"
              value={coverageMetric}
              onChange={setCoverageMetric}
              options={[
                { id: "levels", label: "Insured vs economic $" },
                { id: "share", label: "Insured share %" },
              ]}
            />
          </>
        )}
      </div>

      {view === "bearers" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cumulative share vs equal split"
            subtitle="Residual incidence Lorenz ??? five bearer buckets"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={RESIDUAL_CONCENTRATION_CURVE}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    domain={[0, 100]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 1)}
                    labelFormatter={(l) => String(l)}
                  />
                  <Area
                    type="monotone"
                    dataKey="cumulativeSharePct"
                    name="Cumulative burden"
                    fill="#0ea5e933"
                    stroke="#0ea5e9"
                    strokeWidth={2}
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalSharePct"
                      name="Equal split"
                      stroke="#94a3b8"
                      strokeDasharray="4 4"
                      dot={false}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked residual bearers"
            subtitle={
              ladderMetric === "sharePct"
                ? "Share of residual incidence"
                : "Cumulative incidence share"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={residualBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Bar dataKey="value" name="Share" radius={[0, 4, 4, 0]}>
                    {residualBars.map((b) => (
                      <Cell key={b.id} fill={b.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "mdb" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="MDB climate stacks by income group"
            subtitle="2025 Joint Summary ??? adaptation vs mitigation ($B)"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={MDB_STACKS}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} tickFormatter={(v) => `$${v}B`} />
                  <Tooltip formatter={(v) => fmtBn(Number(v))} />
                  <Bar
                    dataKey="adaptBn"
                    name="Adaptation"
                    stackId="a"
                    fill="#0ea5e9"
                  />
                  {showMitigation && (
                    <Bar
                      dataKey="mitigBn"
                      name="Mitigation"
                      stackId="a"
                      fill="#f59e0b"
                    />
                  )}
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="MDB adaptation book split"
            subtitle={`LMIC ${fmtPct(HEADLINE.mdbLmicShareOfAllAdaptPct)} of all-economy MDB adapt`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={mdbAdaptDonut}
                    dataKey="value"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                  >
                    {mdbAdaptDonut.map((s) => (
                      <Cell key={s.id} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => fmtBn(Number(v))} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-center text-xs text-slate-500">
              Adapt is only {fmtPct(HEADLINE.mdbAdaptShareOfLmicClimatePct)} of
              LMIC climate ({fmtBn(HEADLINE.mdbLmicClimate2025Bn)}) and{" "}
              {fmtPct(HEADLINE.mdbAdaptShareOfTotalClimatePct)} of total MDB
              climate ({fmtBn(HEADLINE.mdbTotalClimate2025Bn)}).
            </p>
          </ChartCard>
        </div>
      )}

      {view === "coverage" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Protection-gap geography"
            subtitle="Swiss Re-style $424B stock ??? regional shares"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={regionBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      gapMetric === "gapBn" ? `$${v}B` : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={80}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) =>
                      gapMetric === "gapBn"
                        ? fmtBn(Number(v))
                        : fmtPct(Number(v), 1)
                    }
                  />
                  <Bar dataKey="value" name="Value" radius={[0, 4, 4, 0]}>
                    {regionBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Resilience ?? gap dollars"
            subtitle="Bubble size ??? gap share of $424B stock"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Resilience %"
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Gap $B"
                    tick={{ fontSize: 11 }}
                    unit="B"
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 280]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) =>
                      name === "Gap $B"
                        ? fmtBn(Number(v))
                        : name === "Resilience %"
                          ? fmtPct(Number(v))
                          : String(v)
                    }
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.shortLabel ?? ""
                    }
                  />
                  <Scatter data={scatterData} name="Regions">
                    {scatterData.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Coverage path ??? insured tip of economic loss"
            subtitle="FY 2025 vs H1 2025 vs H1 2026"
            className=""
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                {coverageMetric === "levels" ? (
                  <ComposedChart data={COVERAGE_PATH}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="shortLabel" tick={{ fontSize: 11 }} />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `$${v}B`}
                    />
                    <Tooltip formatter={(v) => fmtBn(Number(v))} />
                    <Bar
                      dataKey="economicBn"
                      name="Economic"
                      fill="#94a3b8"
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="insuredBn"
                      name="Insured"
                      fill="#0ea5e9"
                      radius={[4, 4, 0, 0]}
                    />
                    <Line
                      type="monotone"
                      dataKey="insuredSharePct"
                      name="Insured share %"
                      stroke="#f43f5e"
                      strokeWidth={2}
                      yAxisId={0}
                      hide
                    />
                  </ComposedChart>
                ) : (
                  <ComposedChart data={COVERAGE_PATH}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="shortLabel" tick={{ fontSize: 11 }} />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      domain={[0, 100]}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <Tooltip formatter={(v) => fmtPct(Number(v))} />
                    <Area
                      type="monotone"
                      dataKey="insuredSharePct"
                      name="Insured share"
                      fill="#0ea5e933"
                      stroke="#0ea5e9"
                      strokeWidth={2}
                    />
                    <Line
                      type="monotone"
                      dataKey="insuredSharePct"
                      name="Share"
                      stroke="#0ea5e9"
                      strokeWidth={2}
                      dot={{ r: 5 }}
                    />
                  </ComposedChart>
                )}
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top-k concentration scoreboard"
            subtitle="Five lenses ??? residual, MDB, gap, donors, instruments"
          >
            <div className="overflow-x-auto">
              <table className="w-full min-w-[28rem] text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 text-xs uppercase tracking-wide text-slate-500">
                    <th className="py-2 pr-3 font-semibold">Lens</th>
                    <th className="py-2 pr-3 font-semibold">Top-1</th>
                    <th className="py-2 pr-3 font-semibold">Top-3</th>
                    <th className="py-2 font-semibold">HHI</th>
                  </tr>
                </thead>
                <tbody>
                  {TOP_K_LADDER.map((row) => (
                    <tr
                      key={row.id}
                      className="border-b border-slate-100 last:border-0"
                    >
                      <td className="py-2.5 pr-3 font-medium text-slate-800">
                        {row.lens}
                      </td>
                      <td className="py-2.5 pr-3 tabular-nums text-slate-700">
                        {fmtPct(row.top1Pct, row.top1Pct % 1 ? 1 : 0)}
                      </td>
                      <td className="py-2.5 pr-3 tabular-nums text-slate-700">
                        {fmtPct(row.top3Pct, row.top3Pct % 1 ? 1 : 0)}
                      </td>
                      <td className="py-2.5 tabular-nums text-slate-700">
                        {row.hhi.toLocaleString("en-US")}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "donors" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Vintage delta ??? prior vs Q3/Aug prints"
            subtitle="Dumbbells across residual tip, MDB, OECD, coverage, scarcity"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={dumbbellRows}
                  layout="vertical"
                  margin={{ left: 8, right: 16 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={96}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, name, item) => {
                      const row = item?.payload as (typeof dumbbellRows)[0];
                      if (!row) return String(v);
                      if (name === "prior")
                        return [formatDeltaValue(row, "prior"), "Prior"];
                      if (name === "newest")
                        return [formatDeltaValue(row, "newest"), "Newest"];
                      return [String(v), String(name)];
                    }}
                  />
                  <Bar
                    dataKey="high"
                    fill="transparent"
                    stroke="transparent"
                    isAnimationActive={false}
                  />
                  <Bar dataKey="prior" name="prior" barSize={0} />
                  <Bar dataKey="newest" name="newest" barSize={0} />
                  {dumbbellRows.map((d) => (
                    <Line
                      key={d.id}
                      data={[
                        { shortLabel: d.shortLabel, v: d.prior },
                        { shortLabel: d.shortLabel, v: d.newest },
                      ]}
                      hide
                    />
                  ))}
                  <Scatter dataKey="prior" fill="#94a3b8" name="Prior">
                    {dumbbellRows.map((d) => (
                      <Cell key={`p-${d.id}`} fill="#94a3b8" />
                    ))}
                  </Scatter>
                  <Scatter dataKey="newest" fill="#0ea5e9" name="Newest">
                    {dumbbellRows.map((d) => (
                      <Cell key={`n-${d.id}`} fill={d.fill} />
                    ))}
                  </Scatter>
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-3 space-y-1 text-xs text-slate-500">
              {VINTAGE_DELTAS.map((d) => (
                <li key={d.id}>
                  <span className="font-medium text-slate-700">
                    {d.shortLabel}:
                  </span>{" "}
                  {formatDeltaValue(d, "prior")} ???{" "}
                  {formatDeltaValue(d, "newest")}
                </li>
              ))}
            </ul>
          </ChartCard>

          <ChartCard
            title="OECD adaptation donor tip"
            subtitle={`${fmtBn(HEADLINE.oecdAdapt2024Bn)} provided/mobilised 2024 ??? estimated shares`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={donorBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Bar dataKey="sharePct" name="Share" radius={[0, 4, 4, 0]}>
                    {donorBars.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Public adaptation instruments"
            subtitle="OECD public adaptation 2024 ??? loan-heavy tip"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={INSTRUMENT_MIX}
                    dataKey="sharePct"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={90}
                    paddingAngle={2}
                  >
                    {INSTRUMENT_MIX.map((s) => (
                      <Cell key={s.id} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <div className="rounded-xl border border-slate-200 bg-slate-50 px-5 py-4 text-sm text-slate-600">
        <p className="font-medium text-slate-800">Sources &amp; notes</p>
        <p className="mt-1 leading-relaxed">{SOURCE_NOTE}</p>
        <ul className="mt-3 list-inside list-disc space-y-1 text-xs text-slate-500">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a
                href={s.url}
                className="text-sky-700 underline-offset-2 hover:underline"
                target={s.url.startsWith("http") ? "_blank" : undefined}
                rel={s.url.startsWith("http") ? "noreferrer" : undefined}
              >
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

